#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *next; };
    struct Node a = {12, NULL};
    struct Node b = {24, &a};
    a.next = &b;
    struct Node *cur = &a;
    cur = cur->next->next;
    printf("%d\n", cur->value);
    return 0;
