#include <stdio.h>

int main(void)
{
    struct Node { struct Node *next; };
    struct Node node;
    node.next = &node;
    struct Node *cur = &node;
    int count = 0;
    do {
        count++;
        cur = cur->next;
    } while (cur != &node);
    printf("%d\n", count);
    return 0;
}

#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *next; };
    struct Node a = {12, NULL};
    struct Node b = {24, &a};
    a.next = &b;
    struct Node *tail = &b;
    tail = tail->next;
    printf("%d\n", tail->next->value);
    return 0;
}
